mapper.select:
SELECT t.quote_id, t.tenant_id, t.instance_id, t.quote_no, t.customer_id, t.customer_name, t.opportunity_id, t.opportunity_name, t.quote_name, t.total_amount, t.tax_amount, t.currency, t.valid_until, t.owner_id, t.owner_name, t.contract_id, t.contract_no, t.attachment_url, t.remark, t.status, t.del_flag, t.create_by, t.create_time, t.update_by, t.update_time, c.dept_id AS scope_dept_id, c.owner_id AS scope_owner_id FROM oa_crm_quote t INNER JOIN oa_crm_customer c ON c.customer_id = t.customer_id AND c.del_flag = '0' WHERE t.del_flag = '0'
AND t.customer_id = #{query.customerId}
AND t.opportunity_id = #{query.opportunityId}
AND t.quote_name LIKE CONCAT('%', #{query.quoteName}, '%')
AND t.status = #{query.status}
ORDER BY t.update_time DESC
